  ('23be7726-ee58-5f2e-ada1-7b4533e9a1fc'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Les levures du boulanger au travail","competence":"lire-graphique","situation":"Une boulangère se demande ce que font les levures de sa pâte. Un technicien mesure leur production dans deux flacons, l’un ouvert à l’air, l’autre fermé.","documents":[{"id":"proto","type":"texte","genre":"consigne","titre":"Protocole","blocs":["Deux flacons contiennent de l’eau, du glucose et des levures de boulanger.","Le flacon 1 reste ouvert, avec du dioxygène. Le flacon 2 est fermé et privé de dioxygène.","On mesure l’éthanol toutes les 30 minutes."],"source":"Texte écrit pour l’exercice"},{"id":"ethanol","type":"graphique","forme":"courbe","titre":"Éthanol dans deux flacons de levures et de glucose","categories":["0","30","60","90"],"series":[{"nom":"Flacon avec dioxygène","valeurs":[0,0,0,0],"teinte":"vert"},{"nom":"Flacon sans dioxygène","valeurs":[0,1.2,2.4,3.6],"teinte":"corail"}],"axeY":{"titre":"Éthanol","unite":"g/L","min":0,"max":4,"pas":1},"axeX":{"titre":"Temps (min)"},"valeurs":false,"source":"Résultats écrits pour l’exercice"}],"questions":[{"enonce":"Quelle teneur en éthanol lit-on à 60 minutes dans le flacon sans dioxygène ?","aide":"Repère 60 sur l’axe horizontal, puis la courbe qui monte.","type":"nombre","unite":"g/L"},{"enonce":"Touche l’instant où le flacon sans dioxygène atteint 3,6 g/L.","aide":"Cherche la dernière mesure de la courbe qui monte.","type":"zone","document":"ethanol","multiple":false},{"enonce":"Pourquoi le flacon avec dioxygène ne produit-il pas d’éthanol ?","aide":"Que fait une levure qui dispose de dioxygène ?","type":"choix","options":[{"id":"a","texte":"Les levures y respirent et dégradent complètement le glucose"},{"id":"b","texte":"Les levures y sont mortes faute de glucose à consommer"},{"id":"c","texte":"Les levures n’y ont besoin d’aucune matière organique"},{"id":"d","texte":"Les levures y fermentent mais l’éthanol s’évapore aussitôt"}],"multiple":false},{"enonce":"Le rythme reste constant : quelle teneur en éthanol à 120 minutes dans le flacon sans dioxygène ?","aide":"Calcule d’abord ce qui est produit en 1 minute (3,6 g/L en 90 minutes).","type":"nombre","unite":"g/L"},{"enonce":"Associe chaque processus à son lieu dans la cellule.","aide":"Une levure n’a pas de chloroplaste mais a des mitochondries.","type":"association","gauche":[{"id":"g0","texte":"Respiration cellulaire"},{"id":"g1","texte":"Fermentation alcoolique"},{"id":"g2","texte":"Photosynthèse"}],"droite":[{"id":"d0","texte":"Cytoplasme"},{"id":"d1","texte":"Chloroplastes"},{"id":"d2","texte":"Mitochondries"}]}]}$ex$::jsonb,
