   $ex${"titre":"Combien de gamètes différents ?","competence":"calculer","situation":"Une généticienne compare le nombre de gamètes différents que peuvent produire cinq espèces, pour comprendre pourquoi deux enfants d’un même couple ne se ressemblent pas toujours.","documents":[{"id":"esp","type":"tableau","titre":"Nombre de paires de chromosomes","colonnes":["Espèce","Paires de chromosomes"],"lignes":[["Drosophile",4],["Petit pois",7],["Maïs",10],["Chat",19],["Humain",23]],"enteteLignes":true,"source":"Valeurs du caryotype"},{"id":"regle","type":"texte","genre":"consigne","titre":"La règle du brassage","blocs":["Pour une espèce qui a n paires de chromosomes, le brassage interchromosomique peut produire 2 puissance n gamètes différents.","Une fécondation réunit un gamète de chaque parent, au hasard."],"source":"On ne tient pas compte du crossing-over"}],"questions":[{"enonce":"Touche l’espèce qui peut produire le moins de gamètes différents.","aide":"Moins de paires de chromosomes, moins de combinaisons.","type":"zone","document":"esp","multiple":false},{"enonce":"Combien de gamètes différents le petit pois peut-il produire ?","aide":"Calcule 2 puissance 7.","type":"nombre","unite":"gamètes"},{"enonce":"Deux drosophiles s’accouplent. Combien de fécondations différentes sont possibles entre leurs gamètes ?","aide":"Chaque parent produit 2⁴ gamètes : multiplie les deux nombres.","type":"nombre","unite":"combinaisons"},{"enonce":"Combien de fois plus de gamètes différents le chat peut-il produire que le maïs ?","aide":"Le chat a 19 − 10 = 9 paires de plus : chaque paire de plus double le nombre.","type":"nombre","unite":"fois"},{"enonce":"Pourquoi deux enfants d’un même couple (hors jumeaux identiques) ne sont-ils pas identiques ?","aide":"Pense au nombre de gamètes possibles et à leur rencontre.","type":"choix","options":[{"id":"a","texte":"Chaque enfant reçoit des gènes qui n’existent pas chez ses parents"},{"id":"b","texte":"Les parents ont changé de génome entre les deux naissances"},{"id":"c","texte":"La mutation transforme tous les gènes à chaque grossesse"},{"id":"d","texte":"Le brassage et la fécondation au hasard combinent les gènes autrement"}],"multiple":false}]}$ex$::jsonb,
