  ('bd0ae00f-ffa7-5a7f-a1d3-d81fc95bb480'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La phalène du bouleau change de couleur","competence":"lire-graphique","situation":"Dans un bois proche d’une ville industrielle, un naturaliste compte les deux formes d’un papillon de nuit, la phalène du bouleau, à trois époques différentes. Les oiseaux la mangent quand ils la voient.","documents":[{"id":"phalene","type":"graphique","forme":"barres","titre":"Les formes de la phalène du bouleau dans un bois","categories":["Avant l’industrie","Industrie et suie","Après dépollution"],"series":[{"nom":"Forme claire","valeurs":[98,5,85],"teinte":"jaune"},{"nom":"Forme sombre","valeurs":[2,95,15],"teinte":"brun"}],"axeY":{"titre":"Part des phalènes","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Époque"},"valeurs":false,"source":"Valeurs simplifiées pour l’exercice"}],"questions":[{"enonce":"Touche l’époque où la forme sombre est la plus fréquente.","aide":"Cherche où la barre de la forme sombre dépasse celle de la forme claire.","type":"zone","document":"phalene","multiple":false},{"enonce":"De combien de points de pourcentage la part de la forme sombre augmente-t-elle entre « avant l’industrie » et « industrie et suie » ?","aide":"Soustrais les deux hauteurs de barre de la forme sombre.","type":"nombre","unite":"points"},{"enonce":"Pourquoi la forme sombre est-elle devenue majoritaire pendant la période de suie ?","aide":"Qui mange les phalènes, et que voit-il sur un tronc noir ?","type":"choix","options":[{"id":"a","texte":"Sur les troncs noircis, elle mangeait davantage de lichens"},{"id":"b","texte":"Sur les troncs noircis, elle était moins visible des oiseaux"},{"id":"c","texte":"La forme claire a été chassée vers d’autres bois"},{"id":"d","texte":"Les suies ont fait muter toutes les phalènes en sombre"}],"multiple":false}]}$ex$::jsonb,
