  ('bd0ae00f-ffa7-5a7f-a1d3-d81fc95bb480'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux populations, un même allèle","competence":"lire-graphique","situation":"Un logiciel simule deux populations d’une même espèce où l’allèle A, ni utile ni nuisible, a au départ la fréquence 0,5. Tu compares l’évolution d’une toute petite population et d’une très grande.","documents":[{"id":"derive","type":"graphique","forme":"courbe","titre":"Fréquence de l’allèle A au fil des générations","categories":["G0","G1","G2","G3","G4","G5"],"series":[{"nom":"Population de 10 individus","valeurs":[0.5,0.4,0.6,0.8,0.9,1],"teinte":"corail"},{"nom":"Population de 1 000 individus","valeurs":[0.5,0.49,0.51,0.5,0.51,0.5],"teinte":"bleu"}],"axeY":{"titre":"Fréquence de l’allèle A","min":0,"max":1,"pas":0.25},"axeX":{"titre":"Génération"},"valeurs":false,"source":"Simulation écrite pour l’exercice : l’allèle A n’apporte aucun avantage"}],"questions":[{"enonce":"Quelle est la fréquence de l’allèle A à la génération G3 dans la population de 10 individus ?","aide":"Repère G3 sur l’axe horizontal, puis la courbe de la petite population.","type":"nombre"},{"enonce":"Touche la génération où l’allèle A est présent chez tous les individus de la petite population.","aide":"La fréquence vaut alors 1.","type":"zone","document":"derive","multiple":false},{"enonce":"Pourquoi la grande population reste-t-elle stable ?","aide":"Pense à l’effet du hasard quand on a beaucoup d’individus.","type":"choix","options":[{"id":"a","texte":"Les individus y sont tous identiques génétiquement"},{"id":"b","texte":"La sélection naturelle y est plus forte que dans une petite"},{"id":"c","texte":"Dans une grande population, les effets du hasard s’annulent en grande partie"},{"id":"d","texte":"Les mutations y sont plus rares que dans une petite population"}],"multiple":false},{"enonce":"La petite population compte 10 individus diploïdes, soit 20 exemplaires du gène. À G4, combien portent l’allèle A ?","aide":"Fréquence 0,9 sur 20 exemplaires.","type":"nombre","unite":"exemplaires"}]}$ex$::jsonb,
