  ('9ddff01e-0bf5-5699-860f-af373ea71c31'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un marais sous pression","competence":"analyser-texte","situation":"Un journaliste local décrit l’évolution d’un marais depuis trente ans. Tu relèves ce que ce reportage dit des causes du recul de la biodiversité.","documents":[{"id":"marais","type":"texte","genre":"article","titre":"Le marais de la Brèche","blocs":["Il y a trente ans, le marais s’étendait jusqu’au village. Depuis, une partie a été drainée pour faire des champs, et une route coupe en deux ce qui reste.","Les pêcheurs se plaignent : la pêche excessive a vidé l’étang de ses brochets.","Dans le canal, une écrevisse exotique, échappée d’un élevage, chasse les écrevisses locales.","Enfin, les engrais des champs voisins finissent dans l’eau et font proliférer les algues."],"source":"Reportage imaginaire, écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui montrent une destruction ou une fragmentation de l’habitat.","aide":"L’un coupe le marais en deux, l’autre l’assèche.","type":"zone","document":"marais","multiple":true},{"enonce":"Touche le mot qui désigne une espèce exotique envahissante.","aide":"Elle a été introduite hors de son aire d’origine.","type":"zone","document":"marais","multiple":false},{"enonce":"Parmi les cinq causes du cours (habitats, surexploitation, pollutions, espèces exotiques envahissantes, changement climatique), combien le reportage en cite-t-il ?","aide":"Relève une cause par paragraphe ; une cause n’est pas citée.","type":"nombre","unite":"causes"}]}$ex$::jsonb,
