  ('9ddff01e-0bf5-5699-860f-af373ea71c31'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Moins de marais, moins de grenouilles ?","competence":"analyser-document","situation":"Une réserve naturelle voit ses grenouilles décliner. Son équipe croise la surface de zone humide et les effectifs, pour savoir si la perte d’habitat suffit à tout expliquer.","documents":[{"id":"zonehum","type":"graphique","forme":"courbe","titre":"Surface de zone humide","categories":["1980","1990","2000","2010"],"series":[{"nom":"Zone humide","valeurs":[40,32,25,20],"teinte":"bleu"}],"axeY":{"titre":"Surface","unite":"km²","min":0,"max":50,"pas":10},"axeX":{"titre":"Année"},"valeurs":false,"source":"Données d’une zone humide imaginaire"},{"id":"gren","type":"tableau","titre":"Effectif de grenouilles de cette zone humide","colonnes":["Année","Effectif"],"lignes":[[1980,"2 400"],[1990,"1 700"],[2000,"1 200"],[2010,"800"]],"enteteLignes":true,"source":"Données imaginaires, écrites pour l’exercice"}],"questions":[{"enonce":"De quel pourcentage la surface de zone humide a-t-elle diminué entre 1980 et 2010 ?","aide":"Perte = 40 − 20 ; compare à la surface de départ.","type":"nombre","unite":"%"},{"enonce":"Quelle était la densité de grenouilles en 1980, en individus par km² ?","aide":"Divise l’effectif de 1980 par la surface de 1980.","type":"nombre","unite":"individus/km²"},{"enonce":"Quelle est la densité de grenouilles en 2010, en individus par km² ?","aide":"Divise l’effectif de 2010 par la surface de 2010.","type":"nombre","unite":"individus/km²"},{"enonce":"La densité passe de 60 à 40 individus par km². Que peut-on en conclure ?","aide":"Si seule la surface comptait, la densité resterait la même.","type":"choix","options":[{"id":"a","texte":"Le déclin est dû uniquement au changement de saison"},{"id":"b","texte":"La perte d’habitat explique à elle seule tout le déclin"},{"id":"c","texte":"Les grenouilles ne dépendent pas de la zone humide"},{"id":"d","texte":"La perte d’habitat n’explique pas tout : une autre cause s’y ajoute"}],"multiple":false},{"enonce":"Classe chaque action : elle aggrave la situation ou elle aide la zone humide.","aide":"Demande-toi si l’action rend l’habitat plus vaste et connecté ou plus réduit.","type":"categories","categories":[{"id":"c0","texte":"Aggrave"},{"id":"c1","texte":"Aide"}],"items":[{"id":"i0","texte":"Créer un corridor entre deux mares"},{"id":"i1","texte":"Restaurer une mare comblée"},{"id":"i2","texte":"Imperméabiliser la rive pour un parking"},{"id":"i3","texte":"Drainer une parcelle pour la cultiver"}]}]}$ex$::jsonb,
