  ('6bb01498-8d14-5728-8e10-38915915f7be'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un carnet de terrain dans le jardin","competence":"analyser-texte","situation":"Maëlle tient un carnet d’observation : en une journée, elle note six scènes où des animaux échangent des signaux. Elle veut les classer.","documents":[{"id":"carnet","type":"texte","genre":"article","titre":"Carnet d’observation","blocs":["Au pied du mur, les fourmis avancent en file, antennes au sol : elles suivent une phéromone déposée par une éclaireuse.","À la nuit tombée, un criquet frotte ses ailes l’une contre l’autre : on l’entend à plus de cent mètres.","Au sommet du pommier, un merle chante pour défendre son territoire.","Dans le jardin, un papillon de nuit mâle remonte la trace invisible d’une femelle qu’il ne voit pas.","Dans le parc voisin, un paon déploie sa roue devant une femelle.","Sur la colline, un cerf montre son large bois à un rival, qui recule sans combat."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui désigne la molécule émise par un individu pour modifier le comportement d’un congénère.","aide":"Le mot est dans la première scène, celle des fourmis.","type":"zone","document":"carnet","multiple":false},{"enonce":"Classe chaque scène selon le canal de communication utilisé.","aide":"Demande-toi quel sens reçoit le signal : odorat, ouïe ou vue.","type":"categories","categories":[{"id":"c0","texte":"Chimique"},{"id":"c1","texte":"Sonore"},{"id":"c2","texte":"Visuel"}],"items":[{"id":"i0","texte":"Le papillon qui remonte une trace invisible"},{"id":"i1","texte":"Le merle qui chante"},{"id":"i2","texte":"Le cerf qui montre son bois"},{"id":"i3","texte":"Le paon qui déploie sa roue"},{"id":"i4","texte":"La file de fourmis sur le mur"},{"id":"i5","texte":"Le criquet qui stridule la nuit"}]},{"enonce":"Associe chaque canal à sa particularité.","aide":"Pense aux caractéristiques propres à chaque canal.","type":"association","gauche":[{"id":"g0","texte":"Sonore"},{"id":"g1","texte":"Chimique"},{"id":"g2","texte":"Tactile"}],"droite":[{"id":"d0","texte":"Passe par le contact, comme le toilettage"},{"id":"d1","texte":"Molécules émises en très faible quantité"},{"id":"d2","texte":"Porte loin, même de nuit"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"Une **phéromone** est une molécule émise par un individu qui modifie le comportement d’un autre individu de la même espèce."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c2","i4":"c0","i5":"c1"}},"explication":"Les fourmis et le papillon utilisent des **phéromones** (chimique), le criquet et le merle le **son**, le paon et le cerf le **visuel**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Le canal **sonore** porte loin et fonctionne de nuit ; le canal **chimique** utilise des phéromones en très faible quantité ; le canal **tactile** repose sur le contact."}]$ex$::jsonb),
