e que du poids des mâles"}],"multiple":false},{"enonce":"Ici, les femelles choisissent le mâle. De quelle forme de sélection sexuelle s’agit-il ?","aide":"Qui choisit qui ?","type":"choix","options":[{"id":"a","texte":"Aucune sélection"},{"id":"b","texte":"Naturelle uniquement"},{"id":"c","texte":"Intrasexuelle"},{"id":"d","texte":"Intersexuelle"}],"multiple":false}]}$ex$::jsonb,
