   $ex${"titre":"La craie : combien de temps pour une falaise ?","competence":"calculer","situation":"Dans une carrière de craie, un guide explique à des élèves que la roche qui les entoure s’est formée au fond d’une mer ancienne. Ils cherchent combien de temps il a fallu.","documents":[{"id":"carriere","type":"texte","genre":"article","titre":"Dans une carrière de craie","blocs":["La falaise de la carrière mesure 150 m de haut et ne contient que de la craie.","La craie est faite de squelettes microscopiques d’algues marines. On y trouve aussi des fossiles d’oursins, animaux marins.","En moyenne, la craie s’est accumulée au rythme de 1 cm tous les 1 000 ans."],"source":"Ordre de grandeur écrit pour l’exercice"},{"id":"cycle","type":"chaine","titre":"Le cycle des roches sédimentaires","disposition":"cycle","noeuds":[{"id":"z1","texte":"Érosion","emoji":"🌧️"},{"id":"z2","texte":"Transport","emoji":"🌊"},{"id":"z3","texte":"Dépôt","emoji":"🏖️"},{"id":"z4","texte":"?","emoji":"🪨"},{"id":"z5","texte":"Soulèvement","emoji":"⛰️"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"},{"de":"z5","a":"z1"}]}],"questions":[{"enonce":"Quel processus manque à la place du « ? » dans le cycle ?","aide":"Après le dépôt, le sédiment doit devenir une roche.","type":"choix","options":[{"id":"a","texte":"L’altération, qui fragilise la roche sur place"},{"id":"b","texte":"La diagenèse, qui transforme le sédiment en roche"},{"id":"c","texte":"L’ablation, qui arrache les débris"},{"id":"d","texte":"La fécondation, qui réunit deux cellules"}],"multiple":false},{"enonce":"Combien de millions d’années a-t-il fallu pour accumuler 150 m de craie ?","aide":"Convertis 150 m en cm, puis multiplie par 1 000 ans par cm.","type":"nombre","unite":"millions d’ans"},{"enonce":"Que disent les fossiles d’oursins sur le milieu où la craie s’est formée ?","aide":"Les oursins vivent dans un milieu précis.","type":"choix","options":[{"id":"a","texte":"C’était un glacier"},{"id":"b","texte":"C’était un désert chaud"},{"id":"c","texte":"C’était un torrent de montagne"},{"id":"d","texte":"C’était un milieu marin"}],"multiple":false},{"enonce":"Range le devenir d’un grain de quartz arraché à un granite.","aide":"Suis le cycle : érosion, transport, dépôt, diagenèse.","type":"ordre","items":[{"id":"a","texte":"Il est cimenté en grès"},{"id":"b","texte":"Il est arraché au granite altéré"},{"id":"c","texte":"Une rivière le transporte"},{"id":"d","texte":"Il se dépose dans un delta"}]}]}$ex$::jsonb,
