ourquoi la parcelle C perd-elle 25 % de ses fruits ?","aide":"Regarde la méthode de la parcelle C : qu’y fait-on contre les ravageurs ?","type":"choix","options":[{"id":"a","texte":"Elle manque de pollinisateurs"},{"id":"b","texte":"Elle est protégée par des haies trop denses"},{"id":"c","texte":"Aucune régulation des ravageurs n’y est organisée"},{"id":"d","texte":"Elle reçoit trop de traitements chimiques"}],"multiple":false},{"enonce":"Associe chaque pratique durable à son principe.","aide":"Pense à la parcelle B : quelles pratiques y retrouves-tu ?","type":"association","gauche":[{"id":"g0","texte":"Lutte biologique"},{"id":"g1","texte":"Lutte intégrée"},{"id":"g2","texte":"Agriculture de précision"},{"id":"g3","texte":"Rotation longue"}],"droite":[{"id":"d0","texte":"Un intrant seulement là où c’est utile"},{"id":"d1","texte":"Utiliser un ennemi naturel du ravageur"},{"id":"d2","texte":"Réserver le produit chimique au dernier recours"},{"id":"d3","texte":"Casser le cycle des ravageurs"}]}]}$ex$::jsonb,
