   $ex${"titre":"Le levier du système de récompense","competence":"experimenter","situation":"Dans les années 1950, des chercheurs ont montré que des rats pouvaient répéter un geste pour activer une zone de leur cerveau liée au plaisir. Une expérience de ce genre est imaginée ici, sous forme simplifiée, pour comprendre le rôle de la dopamine.","documents":[{"id":"appuis","type":"graphique","forme":"barres","titre":"Appuis sur le levier en une heure","categories":["Levier sans effet","Levier qui active le système de récompense","Même levier, récepteurs à dopamine bloqués"],"series":[{"nom":"Appuis par heure","valeurs":[8,600,40],"teinte":"violet"}],"axeY":{"titre":"Nombre d’appuis","unite":"par heure","min":0,"max":700,"pas":100},"valeurs":false,"source":"Expérience imaginée, inspirée de travaux historiques sur le rat"},{"id":"protocole","type":"texte","genre":"consigne","titre":"Protocole","source":"Texte écrit pour l’exercice","blocs":["Trois groupes de rats disposent d’un levier dans leur cage.","Groupe 1 : appuyer sur le levier ne déclenche rien.","Groupe 2 : chaque appui active une zone du système de récompense.","Groupe 3 : même dispositif, mais un médicament empêche la dopamine d’agir sur ses cellules cibles."]}],"questions":[{"enonce":"Touche le groupe qui appuie le plus sur le levier.","aide":"Cherche la barre la plus haute.","type":"zone","document":"appuis","multiple":false},{"enonce":"Le groupe 2 appuie combien de fois plus souvent que le groupe 1 ?","aide":"Divise 600 par 8.","type":"nombre","unite":"fois"},{"enonce":"Que montre la baisse des appuis chez le groupe 3 ?","aide":"Compare les groupes 2 et 3 : ce qui change, c’est l’action de la dopamine.","type":"choix","options":[{"id":"a","texte":"La dopamine participe au renforcement du comportement"},{"id":"b","texte":"Les rats du groupe 3 n’ont plus de cerveau actif"},{"id":"c","texte":"Le médicament augmente le plaisir procuré"},{"id":"d","texte":"La dopamine est un réflexe de la moelle épinière"}],"multiple":false},{"enonce":"Associe chaque structure du système nerveux à son rôle.","aide":"Distingue le niveau automatique (moelle) du niveau cérébral.","type":"association","gauche":[{"id":"g0","texte":"Moelle épinière"},{"id":"g1","texte":"Système de récompense"},{"id":"g2","texte":"Cortex"},{"id":"g3","texte":"Dopamine"}],"droite":[{"id":"d0","texte":"Neurotransmetteur de la récompense"},{"id":"d1","texte":"Mémoire, imaginaire, émotions"},{"id":"d2","texte":"Associe un comportement au plaisir"},{"id":"d3","texte":"Réflexes, par un circuit court"}]}]}$ex$::jsonb,
