  ('7ee7c6a2-9323-5507-9fe7-b51faf3a1cad'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un « oui » obtenu par la peur","competence":"argumenter","situation":"Lina écrit à une amie : son copain la presse d’aller plus loin. Elles discutent du consentement et des endroits où trouver une information fiable. L’affiche de l’infirmerie du lycée les aide.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages entre deux amies","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Inès","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Il veut qu’on aille plus loin. Il dit que si je refuse, c’est que je ne l’aime pas."},{"qui":"Inès","texte":"Et toi, tu en as envie ?"},{"qui":"Lina","texte":"Pas vraiment, mais j’ai peur qu’il me quitte."},{"qui":"Inès","texte":"Un oui obtenu par la peur, ce n’est pas un vrai oui. Même après avoir dit oui, on peut changer d’avis."}],"source":"Dialogue écrit pour l’exercice"},{"id":"affiche","type":"fiche","modele":"affiche","entete":"Infirmerie du lycée","sousTitre":"Des adultes pour répondre à tes questions","emoji":"🩺","lignes":[{"texte":"Infirmière scolaire : bureau 12, mardi et jeudi","id":"z1"},{"texte":"Centre de santé sexuelle : prévention, dépistage, contraception","id":"z2"},{"texte":"Sites publics d’information : repères vérifiés","id":"z3"},{"texte":"Enfance en danger : appeler le 119","id":"z4"}],"pied":"Tout échange est confidentiel.","teinte":"violet"}],"questions":[{"enonce":"Quelle caractéristique du consentement n’est pas respectée dans la situation de Lina ?","aide":"Qu’est-ce qui pousse Lina à dire oui ?","type":"choix","options":[{"id":"a","texte":"Il n’est pas libre : il serait obtenu par la pression"},{"id":"b","texte":"Il n’est pas nécessaire : seule l’une des deux compte"},{"id":"c","texte":"Il n’est pas révocable : elle ne peut rien changer"},{"id":"d","texte":"Il n’est pas éclairé : Lina ne connaît pas son copain"}],"multiple":false},{"enonce":"Associe chaque caractère du consentement à sa signification.","aide":"Pense à ce que dit Inès dans le dernier message.","type":"association","gauche":[{"id":"g0","texte":"Libre"},{"id":"g1","texte":"Éclairé"},{"id":"g2","texte":"Révocable"},{"id":"g3","texte":"Nécessaire"}],"droite":[{"id":"d0","texte":"Sans contrainte ni pression"},{"id":"d1","texte":"Peut être retiré à tout moment"},{"id":"d2","texte":"Donné en connaissance de cause"},{"id":"d3","texte":"Demandé à chaque personne"}]},{"enonce":"Touche la ligne de l’affiche qui indique où trouver un avis personnalisé, dans l’établissement même.","aide":"Cherche un adulte présent au lycée.","type":"zone","document":"affiche","multiple":false},{"enonce":"Classe ces sources d’information sur la santé sexuelle.","aide":"Une source fiable est tenue par des professionnels ou des institutions de santé.","type":"categories","categories":[{"id":"c0","texte":"Source fiable"},{"id":"c1","texte":"Source peu fiable"}],"items":[{"id":"i0","texte":"Infirmerie scolaire"},{"id":"i1","texte":"Rumeurs de la cour de récréation"},{"id":"i2","texte":"Vidéos pornographiques"},{"id":"i3","texte":"Site public d’information en santé"},{"id":"i4","texte":"Médecin"},{"id":"i5","texte":"Forum anonyme"}]},{"enonce":"Que prévoit le droit face à une atteinte sexuelle imposée ?","aide":"Le consentement ne se présume pas.","type":"choix","options":[{"id":"a","texte":"Elle est réglée par l’établissement"},{"id":"b","texte":"Elle est sanctionnée pénalement"},{"id":"c","texte":"Elle est tolérée entre amoureux"},{"id":"d","texte":"Elle n’est jugée que si la victime insiste"}],"multiple":false}]}$ex$::jsonb,
